css_refinement_formula:
/* BITSAT Bright Amber FULL FACE */
.exam-home .bold-exam-card.exam-tone-bitsat {
  --exam-surface: linear-gradient(145deg, #261204 0%, #0D0C10 50%, #3B1B05 100%);
  --exam-polish: linear-gradient(125deg, rgba(245,158,11,0.28) 0%, rgba(254,243,199,0.24) 28%, transparent 58%, rgba(217,119,6,0.20) 100%);
  --exam-accent: #FBBF24;
  --exam-muted: #FDE68A;
  --exam-line: #B45309;
  --exam-button: linear-gradient(180deg, #FDE68A, #F59E0B);
  --exam-button-ink: #0F0903;
  --exam-halo: 245 158 11;
  --shine-delay: 1.7s;
}

/* COMEDK Teal Polished Onyx with Platinum Teal Button */
.exam-home .bold-exam-card.exam-tone-comedk {
  --exam-surface: linear-gradient(145deg, #04181A 0%, #0C0D11 50%, #06282B 100%);
  --exam-polish: linear-gradient(125deg, rgba(20,184,166,0.26) 0%, rgba(204,251,241,0.22) 30%, transparent 60%, rgba(13,148,136,0.18) 100%);
  --exam-accent: #2DD4BF;
  --exam-muted: #CCFBF1;
  --exam-line: #0F766E;
  --exam-button: linear-gradient(180deg, #CCFBF1, #2DD4BF);
  --exam-button-ink: #042222;
  --exam-halo: 20 184 166;
  --shine-delay: 3.4s;
}
